#!/usr/bin/env bash
# AKFC — Demandes (tickets), incrément 3a : back-end de l'espace de traitement (sans écran).
#  router « ticket » + : access (compteurs du menu), inbox (ouvertes / à moi / non attribuées / closes),
#    get (détail : messages + historique), handlers (à qui transmettre), take, transfer (note
#    obligatoire), reply, close, reopen. Visibilité : admin = tout ; sinon catégories des groupes
#    dont on est membre direct.
#  Réponse : l'e-mail part D'ABORD (rien n'est enregistré s'il échoue) ; From noreply@ au nom de la
#    catégorie, Reply-To = adresse de la catégorie, signature = membre connecté, Cci d'archive
#    (TICKET_ARCHIVE_BCC, sinon SMTP_REPLY_TO = contact@), dernier message du demandeur cité,
#    Message-ID conservé (pour rattacher sa réponse plus tard).
#  Avis au club : bouton « Traiter la demande » (lien direct). Comptes @akfc.demo : jamais d'e-mail.
#  Aucune migration. Les 3 fichiers modifiés viennent des incréments 1-2 : ils sont remplacés
#  seulement s'ils sont restés identiques (empreinte vérifiée), sinon arrêt sans rien toucher.
# Usage : bash apply-tickets-increment3a.sh   (AKFC_APPLY_ONLY=1 : applique sans vérifier ni committer)
set -euo pipefail
[ -f "package.json" ] || { echo "ERREUR: racine du repo." >&2; exit 1; }
T="packages/backend/src/modules/tickets"; E="packages/backend/src/email/services/sendTicketEmails.ts"
[ -f "$T/router.ts" ] || { echo "ERREUR: applique d'abord apply-tickets-increment2.sh." >&2; exit 1; }
[ -f "$T/ticketQueries.service.ts" ] && { echo "— déjà appliqué"; exit 0; }
declare -A SUM=(
  ["$T/tickets.service.ts"]="89210b4d1c312a6a71b935126ffdb25447433d3e14d720c4644931eb10f280f4"
  ["$T/router.ts"]="9331881f54ccc459d7c0234902257a3b6f0a895de17c6cfbf145b631d6284fc9"
  ["$E"]="19154f4d4c19e1bc95a8dec10bb44288f4aa51cee4c57b880585cabcefa3eed1"
)
for f in "${!SUM[@]}"; do
  [ "$(sha256sum "$f" | cut -c1-64)" = "${SUM[$f]}" ] || { echo "ERREUR: $f a été modifié depuis sa livraison — rien n'est touché. Envoie-le moi." >&2; exit 1; }
done
BK=/tmp/akfc_tk3a_backup; rm -rf "$BK"; mkdir -p "$BK"
for f in "${!SUM[@]}"; do mkdir -p "$BK/$(dirname "$f")"; cp "$f" "$BK/$f"; done
restore(){ for f in "${!SUM[@]}"; do cp "$BK/$f" "$f"; done; rm -f "$T/ticketQueries.service.ts"; echo "↩ fichiers restaurés à l'identique (aucun commit)."; }

echo "== application =="
echo '' | base64 -d > "$T/tickets.service.ts"
echo '' | base64 -d > "$T/router.ts"
echo '' | base64 -d > "$E"
echo '' | base64 -d > "$T/ticketQueries.service.ts"
echo "  ok  3 fichiers mis à jour, 1 créé"

if [ "${AKFC_APPLY_ONLY:-0}" = "1" ]; then echo "APPLY_ONLY"; exit 0; fi

echo "== pnpm check =="
if ! pnpm check > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"; grep -nE "conventions Next|error TS|Error:" /tmp/akfc_tc.log | head -15; restore; exit 1
fi
echo "  ✅ check OK"

git add "$T" "$E"
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
feat(tickets): espace de traitement côté serveur (liste, prise, transfert, réponse signée, clôture)

